```json
{"tool": "sql", "args": {"query": "SELECT Ref_DOI_number, Cell_architecture, ETL_stack_sequence, HTL_stack_sequence, Perovskite_composition_short_form, JV_default_PCE, JV_default_Voc, JV_default_Jsc, JV_default_FF FROM devices WHERE Cell_architecture = 'nip' AND ETL_stack_sequence LIKE '%SnO2%' AND JV_default_PCE > 0 AND JV_default_PCE IS NOT NULL ORDER BY JV_default_PCE DESC LIMIT 10"}}
```

